    private void DoFileUpload(String filePath) throws IOException {
        Log.d("Test", "file path = " + filePath);
        HttpFileUpload(String.valueOf(IMG_URL) + "android_img_up.cm", "", filePath);
    }

    private void HttpFileUpload(String urlString, String params, String fileName) {
        try {
            this.mFileInputStream = new FileInputStream(fileName);
            this.connectUrl = new URL(urlString);
            Log.d("Test", "mFileInputStream  is " + this.mFileInputStream);
            HttpURLConnection conn = (HttpURLConnection) this.connectUrl.openConnection();
            conn.setDoInput(true);
            conn.setDoOutput(true);
            conn.setUseCaches(false);
            conn.setRequestMethod("POST");
            conn.setRequestProperty("Connection", "Keep-Alive");
            conn.setRequestProperty("Content-Type", "multipart/form-data;boundary=" + this.boundary);
            DataOutputStream dos = new DataOutputStream(conn.getOutputStream());
            dos.writeBytes(String.valueOf(this.twoHyphens) + this.boundary + this.lineEnd);
            dos.writeBytes("Content-Disposition: form-data; name=\"file\";filename=\"" + fileName + "\"" + this.lineEnd);
            dos.writeBytes(this.lineEnd);
            int bytesAvailable = this.mFileInputStream.available();
            int bufferSize = Math.min(bytesAvailable, 1024);
            byte[] buffer = new byte[bufferSize];
            int bytesRead = this.mFileInputStream.read(buffer, 0, bufferSize);
            Log.d("Test", "image byte is " + bytesRead);
            while (bytesRead > 0) {
                dos.write(buffer, 0, bufferSize);
                int bytesAvailable2 = this.mFileInputStream.available();
                bufferSize = Math.min(bytesAvailable2, 1024);
                bytesRead = this.mFileInputStream.read(buffer, 0, bufferSize);
            }
            dos.writeBytes(this.lineEnd);
            dos.writeBytes(String.valueOf(this.twoHyphens) + this.boundary + this.twoHyphens + this.lineEnd);
            Log.e("Test", "File is written");
            this.mFileInputStream.close();
            dos.flush();
            InputStream is = conn.getInputStream();
            StringBuffer b = new StringBuffer();
            while (true) {
                int ch = is.read();
                if (ch == -1) {
                    break;
                } else {
                    b.append((char) ch);
                }
            }
            String s = b.toString();
            Log.d("Test", s);
            this.test = s.split(",");
            this.s_filename = this.test[0];
            this.s_thumb = this.test[1];
            main.wb.loadUrl("javascript:board_upload_image_complete('" + this.s_filename + "','" + this.s_thumb + "')");
            if (menuCode == 100 || menuCode == 200) {
                File file = new File(File_temp);
                if (file.exists()) {
                    file.delete();
                    media_scan(file);
                    Log.d("img", "삭제");
                }
            }
            dos.close();
        } catch (Exception e) {
            Log.d("Test", "exception " + e.getMessage());
        }
    }

    public static synchronized int imgOrientation(String filepath) {
        int degree;
        synchronized (cm.class) {
            degree = 0;
            ExifInterface exif = null;
            try {
                ExifInterface exif2 = new ExifInterface(filepath);
                exif = exif2;
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (exif != null) {
                int orientation = exif.getAttributeInt("Orientation", -1);
                if (orientation != -1) {
                    switch (orientation) {
                        case 3:
                            degree = 180;
                            break;
                        case 6:
                            degree = 90;
                            break;
                        case 8:
                            degree = 270;
                            break;
                    }
                }
            }
        }
        return degree;
    }

